(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.23)*18+Math.sin(x*0.016+t*0.32)*12+Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.cos(x*0.025-t*0.4)*6+Math.sin(y*0.03+t*0.5)*5;
  const w2y = Math.sin(y*0.025+t*0.35)*6+Math.cos(x*0.028-t*0.45)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.14, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.11, 1.8, 1.05],
    [200+Math.sin(t*0.38+6)*110, 220+Math.cos(t*0.48+3)*60, 0.055, 2.4, 1.15],
    [300+Math.cos(t*0.42+2)*85, 30+Math.sin(t*0.58+5)*55, 0.075, 2.2, 0.9]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const base=Math.sin(d*f-t*sp);
    const harm=Math.sin(d*f*1.618-t*sp*0.618+0.5)*0.4;
    const sub=Math.sin(d*f*0.5+t*sp*0.3-1.2)*0.25;
    aS+=(base+harm+sub)*w;
    iS+=(Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*1.3-t*sp*0.4+2.1)*0.3)*w;
    hS+=(Math.sin(d*f*2.1-t*sp*1.3+0.8)*0.2+Math.sin(d*f*0.38+t*sp*0.8-0.6)*0.15)*w;
  }
  const n=src.length, tw=src.reduce((a,s)=>a+s[4],0);
  const act=aS/tw, inh=iS/tw, hh=hS/tw;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.9)*0.5)*0.35;
  const ring=Math.sin(dist*0.08-t*2)*Math.cos(ang*6+t*0.5)*0.3;
  const micro=Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.12+Math.sin((sx*0.2+sy*0.15)+t*4)*0.08;
  const react=Math.tanh((act-inh*0.65+bg*0.25+spiral+ring+micro)*2.0);
  const diff=react-hh*0.4;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{
    let md=999;
    for(let i=0;i<5;i++){
      const vx=120+i*80+Math.sin(t*0.3+i*1.5)*30;
      const vy=60+((i*53)%120)+Math.cos(t*0.25+i*2.1)*25;
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md)md=d;
    }
    return Math.cos(md*0.15)*0.15;
  };
  const v=voronoi();
  const blend=diff*0.55+cell*0.2+v*0.15+spiral*0.1;
  const fin=blend*0.5+0.5;
  const pal=[
    [5,12,45],[12,45,85],[18,85,120],[25,135,135],[45,175,145],
    [140,195,120],[210,190,80],[220,145,65],[195,95,75],[150,50,80],
    [90,25,65],[40,15,55],[5,12,45]
  ];
  const idx=fin*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*sf;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*sf;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*sf;
  const lum=0.82+Math.sin(diff*Math.PI)*0.18+Math.abs(react)*0.05;
  const edge=Math.abs(diff)>0.65?1.12+Math.abs(diff)*0.08:1.0;
  const glow=Math.max(0,1-Math.abs(diff)*2)*0.3;
  const shimmer=Math.sin(fin*12+t*3)*0.03+Math.sin(fin*8-t*2.5)*0.02;
  const L=lum*edge+glow+shimmer;
  return[
    Math.min(255,Math.max(0,(r0*L+glow*30))|0),
    Math.min(255,Math.max(0,(g0*L+glow*50))|0),
    Math.min(255,Math.max(0,(b0*L+glow*40))|0)
  ];
}
